    'rules.copySingular': 'copy',
    'rules.copyPlural': 'copies',
    'rules.detail.1': 'Choose another player and name a number between 2 and 8. If that player holds a card with that number, they are immediately eliminated. If you guess wrong, nothing happens. You cannot guess "1" (Inspector). If all other players are protected by the Lawyer, the Inspector is played without effect.',
    'rules.detail.2': 'Secretly look at another player\'s card. Do not reveal it to anyone else. Use this knowledge wisely on future turns.',
    'rules.detail.3': 'Choose another player. Both of you secretly compare your cards. The player holding the lower number is eliminated from the round. In case of a tie, nothing happens.',
    'rules.detail.4': 'You are immune to all other players\' card effects until the start of your next turn. If all other players are protected by the Lawyer, the current player must target themselves with card effects that require choosing a player.',
    'rules.detail.5': 'Choose any player still in the round (including yourself). That player discards their card without applying its effect (unless it is The Murderer) and draws a new card from the case file. If the case file is empty, the player draws the card set aside at the start. If all other players are protected, you must choose yourself.',
    'rules.detail.6': 'Trade the card in your hand with another player\'s card. You cannot trade with an eliminated player.',
    'rules.detail.7': 'If you ever hold the Accomplice together with the Blackmailer (5) or the Double Agent (6), you must discard the Accomplice. You do not need to reveal your other card.',
    'rules.detail.8': 'If you discard The Murderer for any reason — whether by choice or forced by another card — you are immediately eliminated from the round.',
    'rules.important.label': 'Important',
    'rules.important.line1Pre': 'If you are eliminated, reveal and discard the card in your hand face up ',
    'rules.important.line1Bold': 'without',
    'rules.important.line1Post': ' applying its effect.',
