    'briefing.title': 'Tatort-Briefing',
    'rules.closeAriaLabel': 'Regeln schließen',
    'rules.theCase.title': 'Der Fall',
    'rules.theCase.body': 'Du bist ein Detektiv, der einen Mordfall bearbeitet. In jeder Runde hältst du eine einzelne Karte — deinen Hauptverdächtigen. Ziehe in jedem Zug eine neue Karte, spiele eine aus und nutze ihren Effekt, um Hinweise zu sammeln, Gegner auszuschalten oder dich selbst zu schützen.',
    'rules.theCase.italic': 'Erschließe, was die anderen halten. Beschuldige, schütze, spioniere und blufft euch zur Wahrheit.',
    'briefing.teaser': 'Erschließe, was die anderen halten. Beschuldige, schütze, spioniere und blufft euch zur Wahrheit.',
    'rules.takingTurn.title': 'Ein Zug',
    'rules.takingTurn.step1Bold': 'Ziehe',
    'briefing.step1': 'Zieh eine Karte',
    'rules.takingTurn.step1Rest': ' die oberste Karte aus der Fallakte. Du hältst nun 2 Karten.',
    'rules.takingTurn.step2Bold': 'Spiele eine',
    'briefing.step2': 'Spiele eine deiner beiden Karten',
    'rules.takingTurn.step2Rest': ' deiner beiden Karten offen vor dir aus.',
    'rules.takingTurn.step3Bold': 'Wende ihren Effekt an.',
    'briefing.step3': 'Wende ihren Effekt an',
    'rules.takingTurn.step3Rest': ' Du musst den Effekt anwenden, auch wenn er dir schadet.',
    'rules.cardsOverview.title': 'Karten-Übersicht',
    'rules.cardsOverview.colNumber': '#',
    'rules.cardsOverview.colName': 'Name',
    'rules.cardsOverview.colCopies': 'Anzahl',
    'rules.cardsOverview.colEffect': 'Effekt',
    'rules.endOfRound.title': 'Rundenende',
    'rules.endOfRound.lastStandingBold': 'Letzter im Spiel:',
    'rules.endOfRound.lastStandingRest': ' Alle Spieler bis auf einen wurden ausgeschaltet. Der verbliebene Spieler gewinnt die Runde.',
    'rules.endOfRound.caseFileEmptyBold': 'Fallakte leer:',
    'rules.endOfRound.caseFileEmptyRest': ' Das Deck ist am Ende eines Zuges aufgebraucht. Alle verbliebenen Spieler decken ihre Karten auf. Der Spieler mit der höchsten Zahl gewinnt. Gleichstand? Addiere alle ausgespielten Kartenwerte — die höchste Summe gewinnt.',
    'rules.winning.title': 'Das Spiel gewinnen',
    'rules.winning.body': 'Der erste Spieler, der genug Hinweise sammelt, gewinnt:',
    'rules.winning.colPlayers': 'Spieler',
    'briefing.playersLabel': 'Verdächtige am Tisch',
    'rules.winning.colTokens': 'Hinweise zum Sieg',
    'briefing.tokensLabel': 'Hinweise zur Aufklärung',
    'rules.winning.row2Players': '2 Spieler',
    'rules.winning.row3Players': '3 Spieler',
    'rules.winning.row4Players': '4 Spieler',
    'rules.detailedRules.title': 'Detaillierte Kartenregeln',
    'rules.copySingular': 'Karte',
    'rules.copyPlural': 'Karten',
    'rules.detail.1': 'Wähle einen anderen Spieler und nenne eine Zahl zwischen 2 und 8. Hält dieser Spieler eine Karte mit dieser Zahl, wird er sofort eliminiert. Tippst du falsch, passiert nichts. Du darfst nicht "1" (Inspektor) raten. Sind alle anderen Spieler durch den Anwalt geschützt, wird der Inspektor ohne Wirkung gespielt.',
    'rules.detail.2': 'Sieh dir heimlich die Karte eines anderen Spielers an. Verrate sie niemandem. Nutze dieses Wissen klug in den nächsten Zügen.',
    'rules.detail.3': 'Wähle einen anderen Spieler. Ihr beide vergleicht heimlich eure Karten. Der Spieler mit der niedrigeren Zahl wird aus der Runde eliminiert. Bei Gleichstand passiert nichts.',
    'rules.detail.4': 'Du bist bis zum Beginn deines nächsten Zuges immun gegen alle Karteneffekte anderer Spieler. Sind alle anderen Spieler durch den Anwalt geschützt, muss der aktuelle Spieler bei Karteneffekten, die einen Spieler erfordern, sich selbst wählen.',
    'rules.detail.5': 'Wähle einen beliebigen Spieler, der noch in der Runde ist (auch dich selbst). Dieser Spieler legt seine Karte ohne Wirkung ab (außer es ist Der Mörder) und zieht eine neue Karte aus der Fallakte. Ist die Fallakte leer, zieht der Spieler die zu Beginn beiseitegelegte Karte. Sind alle anderen geschützt, musst du dich selbst wählen.',
    'rules.detail.6': 'Tausche deine Handkarte mit der Karte eines anderen Spielers. Du kannst nicht mit einem ausgeschiedenen Spieler tauschen.',
    'rules.detail.7': 'Hältst du je den Komplizen zusammen mit dem Erpresser (5) oder dem Doppelagenten (6), musst du den Komplizen ablegen. Du musst deine andere Karte nicht aufdecken.',
    'rules.detail.8': 'Legst du Den Mörder aus irgendeinem Grund ab — ob freiwillig oder gezwungen durch eine andere Karte — bist du sofort aus der Runde ausgeschieden.',
    'rules.important.label': 'Wichtig',
    'rules.important.line1Pre': 'Wirst du eliminiert, decke die Karte in deiner Hand offen auf und lege sie ab, ',
    'rules.important.line1Bold': 'ohne',
    'rules.important.line1Post': ' ihren Effekt anzuwenden.',
    'rules.important.line2': 'Spielst du eine Karte, die einen Spieler erfordert, und alle anderen Spieler sind durch den Anwalt geschützt, wird deine Karte ohne Wirkung gespielt.',
    'rules.footer': 'Fallakte · Prime Suspect',
    'tutorial.done': 'Fertig',
