    'rules.theCase.body': 'Eres un detective trabajando en un caso de asesinato. En cada ronda tienes una sola carta — tu sospechoso principal. Roba una nueva carta cada turno, juega una y usa su efecto para reunir información, eliminar oponentes o protegerte.',
    'rules.theCase.italic': 'Deduce qué tienen los demás. Acusa, protege, espía y blufea para llegar a la verdad.',
    'briefing.teaser': 'Deduce qué tienen los demás. Acusa, protege, espía y blufea para llegar a la verdad.',
