    'rules.endOfRound.lastStandingBold': 'Último en pie:',
    'rules.endOfRound.lastStandingRest': ' Todos los jugadores menos uno han sido eliminados. El jugador restante gana la ronda.',
    'rules.endOfRound.caseFileEmptyBold': 'Expediente vacío:',
    'rules.endOfRound.caseFileEmptyRest': ' El mazo se acaba al final del turno de un jugador. Todos los jugadores restantes revelan sus cartas. Gana el jugador con el número más alto. ¿Empate? Suma los valores de todas las cartas jugadas — gana el total más alto.',
    'rules.winning.title': 'Ganar el juego',
    'rules.winning.body': 'El primer jugador en reunir suficientes pistas gana:',
    'rules.winning.colPlayers': 'Jugadores',
    'briefing.playersLabel': 'Sospechosos en la mesa',
    'rules.winning.colTokens': 'Pistas para ganar',
    'briefing.tokensLabel': 'Pistas para resolver el caso',
    'rules.winning.row2Players': '2 jugadores',
    'rules.winning.row3Players': '3 jugadores',
    'rules.winning.row4Players': '4 jugadores',
    'rules.detailedRules.title': 'Reglas detalladas de las cartas',
    'rules.copySingular': 'copia',
    'rules.copyPlural': 'copias',
    'rules.detail.1': 'Elige a otro jugador y di un número entre 2 y 8. Si ese jugador tiene una carta con ese número, queda eliminado de inmediato. Si fallas, no pasa nada. No puedes adivinar "1" (Inspector). Si todos los demás están protegidos por el Abogado, el Inspector se juega sin efecto.',
    'rules.detail.2': 'Mira en secreto la carta de otro jugador. No la reveles a nadie más. Usa esa información sabiamente en turnos futuros.',
    'rules.detail.3': 'Elige a otro jugador. Ambos comparáis vuestras cartas en secreto. El jugador con el número más bajo queda eliminado de la ronda. En caso de empate, no pasa nada.',
    'rules.detail.4': 'Eres inmune a todos los efectos de cartas de otros jugadores hasta el inicio de tu próximo turno. Si todos los demás jugadores están protegidos por el Abogado, el jugador actual debe apuntarse a sí mismo con efectos que requieran elegir un jugador.',
    'rules.detail.5': 'Elige a cualquier jugador todavía en la ronda (incluido tú). Ese jugador descarta su carta sin aplicar su efecto (a menos que sea El Asesino) y roba una nueva del expediente. Si el expediente está vacío, roba la carta apartada al inicio. Si todos los demás están protegidos, debes elegirte a ti mismo.',
    'rules.detail.6': 'Intercambia tu carta con la de otro jugador. No puedes intercambiar con un jugador eliminado.',
    'rules.detail.7': 'Si alguna vez tienes el Cómplice junto con el Chantajista (5) o el Agente Doble (6), debes descartar el Cómplice. No tienes que revelar tu otra carta.',
    'rules.detail.8': 'Si descartas a El Asesino por cualquier razón — ya sea por elección o forzado por otra carta — quedas eliminado de inmediato de la ronda.',
    'rules.important.label': 'Importante',
    'rules.important.line1Pre': 'Si eres eliminado, revela y descarta la carta que tienes en la mano boca arriba ',
    'rules.important.line1Bold': 'sin',
    'rules.important.line1Post': ' aplicar su efecto.',
    'rules.important.line2': 'Si juegas una carta que requiere elegir a un jugador y todos los demás están protegidos por el Abogado, tu carta se juega sin efecto.',
    'rules.footer': 'Resumen del caso · Prime Suspect',
