    'tutorial.slide1Description': 'Un juego de cartas de misterio y asesinato - El anfitrion fue asesinado en una mansion cerrada. Desenmascara al asesino a traves de riesgo, deduccion y suerte!',
    'tutorial.slide2Title': 'Roba y juega',
    'tutorial.slide2Description': 'En tu turno, roba una carta y juega una carta. Cada carta tiene un efecto unico que puede ayudarte o eliminar a otros.',
    'tutorial.slide3Title': 'Efectos de cartas',
