    'rules.copySingular': 'cópia',
    'rules.copyPlural': 'cópias',
    'rules.detail.1': 'Escolha outro jogador e diga um número entre 2 e 8. Se esse jogador tiver uma carta com esse número, ele é eliminado na hora. Se você errar, nada acontece. Você não pode chutar "1" (Inspetor). Se todos os outros estiverem protegidos pelo Advogado, o Inspetor é jogado sem efeito.',
    'rules.detail.2': 'Olhe em segredo a carta de outro jogador. Não revele a ninguém. Use essa informação com sabedoria nos próximos turnos.',
    'rules.detail.3': 'Escolha outro jogador. Vocês dois comparam as cartas em segredo. O jogador com o número mais baixo é eliminado da rodada. Em caso de empate, nada acontece.',
    'rules.detail.4': 'Você fica imune a todos os efeitos de carta dos outros jogadores até o início do seu próximo turno. Se todos os outros jogadores estiverem protegidos pelo Advogado, o jogador atual precisa mirar em si mesmo com efeitos de carta que exijam escolher um jogador.',
    'rules.detail.5': 'Escolha qualquer jogador ainda na rodada (incluindo você). Esse jogador descarta a carta dele sem aplicar o efeito (a não ser que seja O Assassino) e compra uma nova carta do arquivo do caso. Se o arquivo estiver vazio, ele compra a carta separada no início. Se todos os outros estiverem protegidos, você precisa escolher a si mesmo.',
    'rules.detail.6': 'Troque a carta da sua mão com a de outro jogador. Você não pode trocar com um jogador eliminado.',
    'rules.detail.7': 'Se você tiver o Cúmplice junto com o Chantagista (5) ou o Agente Duplo (6), precisa descartar o Cúmplice. Você não precisa revelar a sua outra carta.',
    'rules.detail.8': 'Se você descartar O Assassino por qualquer motivo — por escolha ou forçado por outra carta — você é eliminado da rodada na hora.',
