    'rules.endOfRound.caseFileEmptyRest': ' O baralho esgota-se no fim do turno de um jogador. Todos os jogadores restantes revelam as suas cartas. Ganha quem tiver o número mais alto. Empate? Soma os valores de todas as cartas jogadas — ganha o total mais alto.',
