    'rules.copySingular': 'cópia',
    'rules.copyPlural': 'cópias',
    'rules.detail.1': 'Escolhe outro jogador e diz um número entre 2 e 8. Se esse jogador tiver uma carta com esse número, é eliminado de imediato. Se errares, não acontece nada. Não podes adivinhar "1" (Inspetor). Se todos os outros estiverem protegidos pelo Advogado, o Inspetor é jogado sem efeito.',
    'rules.detail.2': 'Olha em segredo para a carta de outro jogador. Não a reveles a ninguém. Usa esta informação com sensatez nos próximos turnos.',
    'rules.detail.3': 'Escolhe outro jogador. Os dois comparam as cartas em segredo. O jogador com o número mais baixo é eliminado da ronda. Em caso de empate, não acontece nada.',
    'rules.detail.4': 'Ficas imune a todos os efeitos de carta dos outros jogadores até ao início do teu próximo turno. Se todos os outros jogadores estiverem protegidos pelo Advogado, o jogador atual tem de visar-se a si mesmo com efeitos de carta que exijam escolher um jogador.',
    'rules.detail.5': 'Escolhe qualquer jogador ainda na ronda (incluindo tu). Esse jogador descarta a sua carta sem aplicar o efeito (a não ser que seja O Assassino) e compra uma nova carta do ficheiro do caso. Se o ficheiro estiver vazio, compra a carta posta de parte no início. Se todos os outros estiverem protegidos, tens de escolher-te a ti mesmo.',
    'rules.detail.6': 'Troca a carta da tua mão com a de outro jogador. Não podes trocar com um jogador eliminado.',
    'rules.detail.7': 'Se alguma vez tiveres o Cúmplice juntamente com o Chantagista (5) ou o Agente Duplo (6), tens de descartar o Cúmplice. Não precisas de revelar a tua outra carta.',
    'rules.detail.8': 'Se descartares O Assassino por qualquer motivo — por escolha ou forçado por outra carta — és eliminado de imediato da ronda.',
