    'rules.detail.5': '選擇仍在這一回合中的任一名玩家（包括你自己）。該玩家在不套用效果的情況下棄掉他的牌（除非那是兇手），並從案件檔案抽一張新牌。如果案件檔案已空，該玩家抽取開局時擱置的那張牌。如果所有其他玩家都受到保護，你必須選擇你自己。',
    'rules.detail.6': '將你手上的牌與另一名玩家的牌交換。你不能與已淘汰的玩家交換。',
    'rules.detail.7': '如果你同時握有共犯與勒索者（5）或雙面間諜（6），你必須棄掉共犯。你不需要透露你的另一張牌。',
    'rules.detail.8': '如果你因任何原因棄掉兇手 — 無論是出於選擇還是被另一張牌強迫 — 你都會立即被淘汰出這一回合。',
    'rules.important.label': '重要',
    'rules.important.line1Pre': '如果你被淘汰，請將你手上的牌正面朝上亮出並棄掉，',
    'rules.important.line1Bold': '不要',
    'rules.important.line1Post': '套用它的效果。',
    'rules.important.line2': '如果你打出一張需要選擇玩家的牌，而所有其他玩家都受到律師保護，你的牌打出後不會產生效果。',
