export const languageNames = {
  en: 'English',
  de: 'Deutsch',
  es: 'Espanol',
  'pt-BR': 'Portugues (BR)',
  'pt-PT': 'Portugues (PT)',
  'zh-Hant': '繁體中文',
};

export const languageFlags = {
  en: '🇺🇸',
  de: '🇩🇪',
  es: '🇪🇸',
  'pt-BR': '🇧🇷',
  'pt-PT': '🇵🇹',
  // Traditional Chinese uses a neutral text badge, not a national flag.
  'zh-Hant': '繁',
};

// Translation key type (export for callers that want strong typing).
export type TranslationKey = keyof typeof translations.en;

// Simple translation function. Accepts any string at call sites (runtime lookup
// with graceful fallback to the raw key) so the many `key as string` / dynamic
// callers across the ported game compile under tsc.
export const getTranslation = (key: TranslationKey | string, language: Language = 'en'): string => {
  const k = key as TranslationKey;
  return translations[language]?.[k] || translations.en[k] || (key as string);
};

// Storage keys
// Prime Suspect ships TWO translation systems (this in-game util + the shell
// `utils/translations.ts`). They MUST read the same precedence and write the
// same key set, or half the UI stays in the old language when you switch.
//   - `gamebuddies-language`  : shared GameBuddies.io platform language
//   - `heartsgambit-language` : legacy in-game key
//   - `primesuspect_language` : the shell's key (STORAGE_KEYS.LOCAL.LANGUAGE)
const GAMEBUDDIES_LANGUAGE_KEY = 'gamebuddies-language';
const LOCAL_LANGUAGE_KEY = 'heartsgambit-language';
const SHELL_LANGUAGE_KEY = 'primesuspect_language';

// Get current language from localStorage
// Checks GameBuddies.io platform language first for seamless integration
const SUPPORTED_LANGUAGES: Language[] = ['en', 'de', 'es', 'pt-BR', 'pt-PT', 'zh-Hant'];
const isSupportedLanguage = (value: string | null): value is Language =>
  value !== null && (SUPPORTED_LANGUAGES as string[]).includes(value);

export const getCurrentLanguage = (): Language => {
  // First check GameBuddies.io platform language
  const platformLang = localStorage.getItem(GAMEBUDDIES_LANGUAGE_KEY);
  if (isSupportedLanguage(platformLang)) {
    return platformLang;
  }
  // Then the legacy in-game key
  const localLang = localStorage.getItem(LOCAL_LANGUAGE_KEY);
  if (isSupportedLanguage(localLang)) {
    return localLang;
  }
  // Then the shell's key, so a language picked in the shell UI is honoured here too
  const shellLang = localStorage.getItem(SHELL_LANGUAGE_KEY);
  if (isSupportedLanguage(shellLang)) {
    return shellLang;
  }
  // Auto-detect from browser
  const fullLang = navigator.language.toLowerCase();
  const baseLang = fullLang.split('-')[0];
  // Traditional Chinese: zh-Hant / zh-TW / zh-HK / zh-MO
  if (fullLang.includes('hant') || fullLang.startsWith('zh-tw') || fullLang.startsWith('zh-hk') || fullLang.startsWith('zh-mo')) {
    return 'zh-Hant';
  }
  // Portuguese variants: respect region tag, default bare "pt" to Brazilian (largest market)
  if (baseLang === 'pt') {
    if (fullLang === 'pt-pt' || fullLang === 'pt') return fullLang === 'pt-pt' ? 'pt-PT' : 'pt-BR';
    return 'pt-BR';
  }
  if (baseLang === 'es') return 'es';
  if (baseLang === 'de') return 'de';
  // Default to English
  return 'en';
};

// Set language in localStorage
// Writes ALL three language keys so the shell + in-game systems stay in sync.
export const setCurrentLanguage = (language: Language): void => {
  const previous = getCurrentLanguage();
  localStorage.setItem(LOCAL_LANGUAGE_KEY, language);
  localStorage.setItem(GAMEBUDDIES_LANGUAGE_KEY, language);
  localStorage.setItem(SHELL_LANGUAGE_KEY, language);
  if (previous !== language) {
    window.dispatchEvent(new Event('languagechange'));
  }
}; 
